function buildPL(fd, yr, m, cm, mode) {
  // For PL lines (Net Sales, COGS, etc.) - have Forecast data
  const getPL = (pl) => {
    if (mode === "forecast") return gV(fd, pl, "Forecast", yr, m);
    if (mode === "reales") return m <= cm ? gV(fd, pl, "Reales", yr, m) : 0;
    // consolidado: reales up to cm (fallback to forecast if no reales), forecast after cm
    if (m <= cm) return gV(fd, pl, "Reales", yr, m);
    return gV(fd, pl, "Forecast", yr, m);
  };
  // For OpEx lines (codes) - only have Reales data
  const getOpex = (pl) => {
    if (mode === "forecast") return gV(fd, pl, "Forecast", yr, m);
    if (mode === "reales") return m <= cm ? gV(fd, pl, "Reales", yr, m) : 0;
    // consolidado: reales up to cm, forecast after
    if (m <= cm) return gV(fd, pl, "Reales", yr, m);
    return gV(fd, pl, "Forecast", yr, m);
  };
{/* */}
  const ns = getPL("Net Sales");
  const cogs = getPL("COGS");
  const gp = ns - cogs;
  const gmPct = ns ? gp / ns : 0;
const sw = getOpex("Salaries & Wages");
const sm = getOpex("Sales & Marketing");
const ta = getOpex("Travel & Accomodation");
const pf = getOpex("Professional Fees");
const of_ = getOpex("Office Expense");
const reg = getOpex("Regulatory");
const sh = getOpex("Software & Hardware");
const mob = getOpex("Mobility");
  const qual = mode === "reales" ? 0 : gV(fd, "Quality", "Forecast", yr, m); // Quality is forecast only
  const ops = getOpex("Operations");
const oth = getOpex("Others");
const totOpex = sw + sm + ta + pf + of_ + reg + sh + mob + qual + ops + oth;
  const totOpexPct = ns ? totOpex / ns : 0;
  const ebitda = gp - totOpex;
  const ebitdaPct = ns ? ebitda / ns : 0;
  const depr = getOpex("Depreciation & Amortization");
  const ebit = ebitda - depr;
  const ebitPct = ns ? ebit / ns : 0;
  const fi = getOpex("Financial Income");
  const fe = getOpex("Financial Expense");
  const totFin = fi + fe;
  const netProfit = ebit - totFin;
  const netProfitPct = ns ? netProfit / ns : 0;
{/* */}
  return { ns, cogs, gp, gmPct, sw, sm, ta, pf, of: of_, reg, sh, mob, qual, ops, oth, totOpex, totOpexPct, ebitda, ebitdaPct, depr, ebit, ebitPct, fi, fe, totFin, netProfit, netProfitPct };
}
